#!/usr/bin/env node
/**
 * Tests for `--targeted` in scripts/gate.mjs: the template needs {files}, the test files changed since --head
 * (tracked diff without deletes, plus untracked) replace it quoted, zero files or too many run the full --test
 * command, the last line says which ran, and a targeted green never lets a later full gate skip.
 * Each case runs in its own temp git repository.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'scripts', 'gate.mjs');
const FULL = 'node -e "console.log(\'FULL\')"';
const TARGETED = 'node args.js {files}';   // args.js prints the arguments it got as one JSON array
const created = [];

process.on('exit', () => {
  for (const dir of created) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp, let the OS have it */ }
  }
});

const git = (root, ...args) => spawnSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', ...args], { cwd: root, encoding: 'utf8' }).stdout.trim();
const { NODE_TEST_CONTEXT, ...env } = process.env;
const gate = (root, ...args) => spawnSync(process.execPath, [SCRIPT, '--root', root, ...args], { encoding: 'utf8', env });
const lastLine = (res) => JSON.parse(res.stdout.trim().split(/\r?\n/).pop());
const logOf = (root) => readFileSync(join(root, '.git', 'deliver', 'gate.log'), 'utf8');
const argvOf = (root) => JSON.parse(logOf(root).split(/\r?\n/).find((l) => l.startsWith('[')));

/** A repo whose head holds committed tests; then a.test.mjs is edited, gone.test.mjs deleted, lib.js edited and "new one.test.mjs" added. */
function repoWithChanges() {
  const root = mkdtempSync(join(tmpdir(), 'gate-targeted-'));
  created.push(root);
  git(root, 'init');
  writeFileSync(join(root, 'args.js'), 'console.log(JSON.stringify(process.argv.slice(2)));\n');
  for (const f of ['a.test.mjs', 'b c.test.mjs', 'gone.test.mjs', 'lib.js']) writeFileSync(join(root, f), 'x\n');
  git(root, 'add', '-A');
  git(root, 'commit', '-m', 'init');
  const head = git(root, 'rev-parse', 'HEAD');
  writeFileSync(join(root, 'a.test.mjs'), 'edited\n');
  writeFileSync(join(root, 'lib.js'), 'edited\n');
  rmSync(join(root, 'gone.test.mjs'));
  writeFileSync(join(root, 'new one.test.mjs'), 'x\n');
  return { root, head };
}

const run = (r, ...args) => gate(r.root, '--head', r.head, '--no-scope', ...args);

test('given a --targeted template without {files}, when the gate runs, then it exits 2 and runs nothing', () => {
  // Given
  const r = repoWithChanges();

  // When
  const res = run(r, '--test', FULL, '--targeted', 'node args.js');

  // Then
  assert.equal(res.status, 2);
  assert.match(res.stderr, /\{files\}/);
});

test('given changed, deleted and untracked test files, when the gate runs targeted, then the live ones replace {files} quoted and the deleted one is left out', () => {
  // Given
  const r = repoWithChanges();

  // When
  const res = run(r, '--test', FULL, '--targeted', TARGETED);

  // Then
  assert.equal(res.status, 0);
  assert.deepEqual(argvOf(r.root).sort(), ['a.test.mjs', 'new one.test.mjs']);
});

test('given a targeted run on two test files, when the gate ends, then the last line says tests targeted:2', () => {
  // Given
  const r = repoWithChanges();

  // When
  const res = run(r, '--test', FULL, '--targeted', TARGETED);

  // Then
  assert.equal(lastLine(res).tests, 'targeted:2');
});

test('given no changed test file, when the gate runs targeted, then the full --test command runs and the line says tests full', () => {
  // Given
  const r = repoWithChanges();
  git(r.root, 'add', '-A');
  git(r.root, 'commit', '-m', 'all in');
  const head = git(r.root, 'rev-parse', 'HEAD');

  // When
  const res = gate(r.root, '--head', head, '--no-scope', '--test', FULL, '--targeted', TARGETED);

  // Then
  assert.match(logOf(r.root), /FULL/);
  assert.equal(lastLine(res).tests, 'full');
});

test('given more changed test files than the cap, when the gate runs targeted, then the full --test command runs', () => {
  // Given
  const r = repoWithChanges();
  for (let i = 0; i < 31; i++) writeFileSync(join(r.root, `t${i}.test.mjs`), 'x\n');

  // When
  const res = run(r, '--test', FULL, '--targeted', TARGETED);

  // Then
  assert.match(logOf(r.root), /FULL/);
  assert.equal(lastLine(res).tests, 'full');
});

test('given a targeted green, when a full gate runs on the same tree, then it runs and is not skipped', () => {
  // Given
  const r = repoWithChanges();
  const targeted = run(r, '--test', FULL, '--targeted', TARGETED);
  assert.equal(lastLine(targeted).gate, 'green');

  // When
  const full = run(r, '--test', FULL);

  // Then
  assert.equal(lastLine(full).gate, 'green');
  assert.match(logOf(r.root), /FULL/);
});

test('given a changed test file whose name holds a shell character, when the gate runs targeted, then the full --test command runs', () => {
  for (const name of ['a;b.test.mjs', 'a&b.test.mjs', '-r.test.mjs', '@r.test.mjs']) {
    // Given
    const r = repoWithChanges();
    writeFileSync(join(r.root, name), 'x\n');

    // When
    const res = run(r, '--test', FULL, '--targeted', TARGETED);

    // Then
    assert.match(logOf(r.root), /FULL/, name);
    assert.equal(lastLine(res).tests, 'full', name);
  }
});

test('given a changed test file with brackets and parentheses in its path, when the gate runs targeted, then it stays targeted', () => {
  // Given
  const r = repoWithChanges();
  writeFileSync(join(r.root, '[id] (group).test.mjs'), 'x\n');

  // When
  const res = run(r, '--test', FULL, '--targeted', TARGETED);

  // Then
  assert.equal(lastLine(res).tests, 'targeted:3');
});
